\title{Density Forces Structure: Extremal Bounds for Cliques, Shadows, and Arithmetic Progressions}
\author{Aristotle}
\date{2026-06-29}

\begin{document}

\begin{abstract}
We present a unified development of four cornerstone results in extremal combinatorics, each an instance of a single guiding principle: \emph{sufficient density forces unavoidable structure}. First, we establish Tur\'an's theorem in a clean closed integer form---every $K_{r+1}$-free graph on $n$ vertices satisfies $2r\,e(G) \le (r-1)n^2$---and specialize it to Mantel's theorem $4e(G) \le n^2$ for triangle-free graphs, together with a sharp extremal witness showing the Mantel bound is attained exactly by balanced complete bipartite graphs. Second, we extract from the Kruskal--Katona theorem a directly applicable single-shadow lower bound: an $r$-uniform family with at least $\binom{k}{r}$ members has a shadow of size at least $\binom{k}{r-1}$; its $r=2$ specialization states that $\binom{k}{2}$ edges must touch at least $k$ vertices. Third, we present Roth's theorem on three-term arithmetic progressions in a \emph{positive} existence form: a sufficiently dense subset of a finite abelian group contains a genuine non-degenerate progression $a, a+d, a+2d$ with $d \ne 0$, specialized to the cyclic groups $\Z/N\Z$. We discuss the regularity and removal-lemma machinery linking these graph- and number-theoretic phenomena, give algorithms, and outline future research directions.
\end{abstract}

\maketitle

\section{Introduction}

Extremal combinatorics studies how large a discrete structure can be while avoiding a forbidden configuration, and what the near-maximal structures must look like. A recurring meta-theorem governs the field: \emph{once a structure surpasses a density threshold, the forbidden pattern becomes unavoidable, and the structures that come closest to avoiding it are rigid and highly symmetric.}

This paper assembles four classical pillars of the subject around this meta-theorem: Tur\'an's theorem and its progenitor Mantel's theorem (edge density forces large cliques); the Kruskal--Katona theorem (the size of a uniform set family forces the size of its shadow); and Roth's theorem (density of a subset of an abelian group forces three-term arithmetic progressions).

Throughout, $G$ denotes a finite simple graph with vertex set $V(G)$, $n = |V(G)|$, and edge set $E(G)$; we write $\eG = |E(G)|$. For a positive integer $r$, $K_r$ is the complete graph (clique) on $r$ vertices. We say $G$ is \emph{$K_r$-free} if it contains no subgraph isomorphic to $K_r$.

\section{Tur\'an's and Mantel's theorems}

\begin{definition}
A \emph{clique} in $G$ of size $r$ is a set of $r$ pairwise-adjacent vertices. A graph is \emph{$K_{r+1}$-free} if it has no clique of size $r+1$. The \emph{Tur\'an graph} $T(n,r)$ is the complete $r$-partite graph on $n$ vertices whose parts are as equal as possible: two vertices are adjacent if and only if they lie in distinct parts.
\end{definition}

\begin{theorem}[Tur\'an, closed integer form]\label{thm:turan}
If $G$ is a $K_{r+1}$-free graph on $n$ vertices with $r \ge 1$, then
\[
2r \cdot \eG \;\le\; (r-1)\, n^2,
\qquad\text{equivalently}\qquad
\eG \le \left(1 - \tfrac{1}{r}\right)\frac{n^2}{2}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
The sharp form of Tur\'an's theorem identifies $T(n,r)$ as the unique edge-maximizer among $K_{r+1}$-free graphs on $n$ vertices; hence $\eG \le e(T(n,r))$. Writing $n = qr + s$ with $0 \le s < r$,
\[
e(T(n,r)) = \frac{n^2 - s^2}{2}\cdot\frac{r-1}{r} + \binom{s}{2},
\]
and the integer remainder terms are bounded so that $e(T(n,r)) \le \frac{r-1}{2r}n^2$. Multiplying by $2r$ gives the claim. An equivalent route uses Zykov symmetrization: shifting weight toward a balanced complete $r$-partite configuration never decreases the edge count.
\end{proof}

\begin{theorem}[Mantel]\label{thm:mantel}
A triangle-free graph $G$ on $n$ vertices satisfies $4\,\eG \le n^2$.
\end{theorem}

\begin{proof}[Proof sketch]
Apply Theorem~\ref{thm:turan} with $r = 2$: $K_3$-free is $K_{r+1}$-free for $r = 2$, giving $4\,\eG \le n^2$.
\end{proof}

\begin{theorem}[Sharpness of Mantel]\label{thm:mantelsharp}
For every $k \in \mathbb{N}$, the balanced complete bipartite graph $K_{k,k}$ (the Tur\'an graph $T(2k,2)$) on $n = 2k$ vertices is triangle-free and satisfies $4\,e = n^2$ with equality.
\end{theorem}

\begin{proof}[Proof sketch]
$K_{k,k}$ is bipartite, hence triangle-free, and has $e = k^2$ edges, so $4e = 4k^2 = (2k)^2 = n^2$.
\end{proof}

\section{The Kruskal--Katona shadow bound}

\begin{definition}
A family $\mathcal A$ of subsets of an $n$-element set is \emph{$r$-uniform} if every member has exactly $r$ elements. Its \emph{shadow} is
\[
\shadow \mathcal A = \{\, B : |B| = r-1,\ B \subseteq A \text{ for some } A \in \mathcal A \,\},
\]
the family of all $(r-1)$-subsets obtained by deleting one element from a member.
\end{definition}

\begin{theorem}[Single-shadow Kruskal--Katona]\label{thm:kk}
Let $1 \le r \le k \le n$ and let $\mathcal A$ be an $r$-uniform family of subsets of an $n$-element set with $|\mathcal A| \ge \binom{k}{r}$. Then
\[
|\shadow \mathcal A| \;\ge\; \binom{k}{r-1}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
The Lov\'asz form of Kruskal--Katona states that for each $i \ge 1$, if $|\mathcal A| \ge \binom{k}{r}$ then $|\shadow^{(i)} \mathcal A| \ge \binom{k}{r-i}$. Taking $i = 1$ gives the claim. The hypotheses $1 \le r \le k \le n$ ensure the relevant binomial coefficients are non-degenerate and a witnessing colex-initial family exists.
\end{proof}

\begin{corollary}[Edge density forces vertex spread]\label{cor:edges}
Let $2 \le k \le n$ and let $E$ be a family of $2$-element subsets of an $n$-element vertex set with $|E| \ge \binom{k}{2}$. Then the set of covered vertices satisfies $|\shadow E| \ge k$.
\end{corollary}

\begin{proof}[Proof sketch]
Apply Theorem~\ref{thm:kk} with $r = 2$, using $\binom{k}{1} = k$. A $2$-set is an edge, and its shadow is the set of incident singleton vertices.
\end{proof}

The bound is tight: the clique $K_k$ has exactly $\binom{k}{2}$ edges on exactly $k$ vertices.

\section{Roth's theorem on three-term arithmetic progressions}

\begin{definition}
Let $G$ be a finite abelian group, written additively. A \emph{three-term arithmetic progression (3-AP)} is a triple $(a,\ a+d,\ a+2d)$; it is \emph{non-degenerate} if $d \ne 0$. A set $A \subseteq G$ is \emph{$3$-AP-free} if whenever $a, b, c \in A$ satisfy $a + c = 2b$ then $a = b = c$.
\end{definition}

\begin{theorem}[Roth, positive form]\label{thm:roth}
Let $G$ be a finite abelian group and $\varepsilon > 0$. There is an effective threshold $B(\varepsilon)$ such that if $|G| \ge B(\varepsilon)$ and $A \subseteq G$ satisfies $|A| \ge \varepsilon |G|$, then $A$ contains a non-degenerate three-term arithmetic progression: there exist $a, d \in G$ with $d \ne 0$ and
\[
a \in A,\qquad a + d \in A,\qquad a + 2d \in A.
\]
\end{theorem}

\begin{proof}[Proof sketch]
The quantitative Roth/corners theorem gives that under the stated hypotheses $A$ is not $3$-AP-free. Negating the definition yields $a, b, c \in A$ with $a + c = b + b$ and $a \ne b$. Set $d := b - a$; then $b = a + d$, and from $a + c = 2b$ we get $c = 2(a+d) - a = a + 2d$. Non-degeneracy $d \ne 0$ follows since $d = 0$ would force $a = b$. Hence $(a, a+d, a+2d)$ is a non-degenerate 3-AP in $A$.
\end{proof}

\begin{corollary}[Roth in $\Z/N\Z$]\label{cor:roth}
Let $N \ge 1$ and $\varepsilon > 0$ with $N \ge B(\varepsilon)$. If $A \subseteq \Z/N\Z$ satisfies $|A| \ge \varepsilon N$, then $A$ contains a non-degenerate 3-AP $a, a+d, a+2d$ with $d \ne 0$.
\end{corollary}

\begin{proof}[Proof sketch]
Apply Theorem~\ref{thm:roth} with $G = \Z/N\Z$ and $|G| = N$.
\end{proof}

\section{The common thread: density forces structure}

The four theorems are instances of one principle. Among $K_{r+1}$-free graphs, edge density is maximized by the balanced Tur\'an graph; among $r$-uniform families of a given size, the shadow is minimized by the colex-initial family; among subsets of an abelian group, $3$-AP-freeness caps density.

The deep bridge is the \emph{regularity method}. Szemer\'edi's regularity lemma partitions any large graph into a bounded number of parts so that almost all pairs behave pseudorandomly. Within such a partition the count of any fixed small subgraph can be estimated as if edges were random, yielding the triangle removal lemma:

\begin{theorem}[Triangle Removal Lemma]
For every $\delta > 0$ there is $\gamma > 0$ such that any $n$-vertex graph with at most $\gamma n^3$ triangles can be made triangle-free by deleting at most $\delta n^2$ edges.
\end{theorem}

Roth's theorem follows by encoding a progression-free set $A \subseteq \Z/N\Z$ as a tripartite graph whose triangles correspond to 3-APs in $A$. Progression-freeness makes these triangles essentially edge-disjoint, so the removal lemma forces few triangles, hence small $|A|$. This is the precise sense in which ``edge density forcing triangles'' and ``set density forcing progressions'' are the same theorem.

A complementary first-moment viewpoint compares the \emph{expected} number $\binom{n}{r}p^{\binom{r}{2}}$ of $r$-cliques in a random graph against the \emph{deterministic} extremal count (e.g.\ the $0$ triangles of $T(2k,2)$ versus the $\binom{n}{3}$ potential triangles of the complete graph), pinching the density of forbidden configurations from two sides.

\section{Algorithms}

\begin{enumerate}[leftmargin=*]
\item \textbf{Tur\'an bound checker.} Given $n,r$, write $n = qr+s$ and compute $e(T(n,r)) = \binom{n}{2} - s\binom{q+1}{2} - (r-s)\binom{q}{2}$; verify $e(T(n,r)) \le \frac{r-1}{2r}n^2$. Cost $O(1)$.
\item \textbf{Shadow computation.} For an explicit $r$-uniform family, generate all single-element deletions and deduplicate; verify $|\shadow\mathcal A| \ge \binom{k}{r-1}$. Cost $O(|\mathcal A|\, r)$.
\item \textbf{Progression search.} Scan $a \in A$, nonzero $d$, and report the first $(a,a+d,a+2d) \subseteq A$; a Fourier count gives $\approx |A|^3/N$ progressions. Cost $O(N^2)$ brute force, $O(N\log N)$ via FFT.
\end{enumerate}

\section{Discussion and future work}

\begin{enumerate}[leftmargin=*]
\item \textbf{Stability for Mantel/Tur\'an.} Near-extremal triangle-free graphs are conjectured to be $O(c)$-close to balanced bipartite.
\item \textbf{Quantitative Roth.} Replace fixed $\varepsilon$ by $\varepsilon(N) \to 0$, tracking how small density may shrink with $N$.
\item \textbf{Iterated-shadow rigidity.} For $|\mathcal A| = \binom{k}{r}$, equality $|\shadow^{(i)}\mathcal A| = \binom{k}{r-i}$ should characterize the colex-isomorphic full $k$-set system.
\item \textbf{Hypergraph removal.} Leverage deterministic-vs-random counts toward corner-free sparsity and multidimensional Roth.
\item \textbf{Spectral Mantel.} A triangle-free graph should satisfy $\lambda_1(G) \le \sqrt{e}$, extremal at $K_{k,k}$.
\end{enumerate}

\section{Conclusion}

Across graphs, set systems, and the integers, one law recurs: cross a density threshold and forbidden structure becomes inevitable, while the objects that barely avoid it are forced into rigid, symmetric shapes. Tur\'an's and Mantel's theorems quantify it for cliques, Kruskal--Katona for shadows, and Roth's theorem for arithmetic progressions---and the regularity method reveals these as facets of one phenomenon.

\end{document}

